import { IFundCreateDTO, IFundUpdateDTO } from '../@types/funds.dto.types';
import { IFund } from '../@types/funds.types';

export const mapFrontFundToCreateDto = (data: IFund): IFundCreateDTO => {
  return {
    name: data.name,
    description: data.description,
    is_active: data.is_active ? 1 : 0,
    is_public: data.is_public ? 1 : 0,
  };
};

export const mapFrontFundToUpdateDto = (data: IFund): IFundUpdateDTO => {
  return {
    id: data.id,
    ...mapFrontFundToCreateDto(data),
  };
};
